//=============================================================================
// tb_weight_path : LOAD_W frame -> weight_loader -> weight_bank -> reader
//
//   The MPU stream test stubs a zero-weight source, so the loader/bank/reader
//   chain has no numeric coverage.  This test drives a real packed frame --
//   the bytes scripts/hw_pack.py produces for an AWQ tile -- through the real
//   RTL and checks every B beat the reader hands to the MPU.
//
//   Inputs (generated by build/real/mk_wtest.py):
//     w_cmd.hex    512-bit LOAD_W command
//     w_frame.hex  128-bit data beats of the frame
//     w_exp.hex    2304-bit expected B beat per K step
//     w_cfg.txt    "<k_steps> <n_grp> <beats>"
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

`include "npu_defs.vh"

module tb_weight_path;

    localparam GROUPS  = 8;
    localparam K_STEPS = 256;
    localparam TW      = `NPU_WTILE_W;

    reg clk = 0, rst_n = 0;
    always #5 clk = ~clk;

    integer errors = 0;

    // ---------------- stimulus files ----------------
    reg [511:0]  cmd_mem  [0:0];
    reg [127:0]  frame    [0:1023];
    reg [2303:0] exp_mem  [0:1023];
    integer      k_steps, n_grp, n_beats;
    integer      fd, rc;

    initial begin
        fd = $fopen("build/real/w_cfg.txt", "r");
        rc = $fscanf(fd, "%d %d %d", k_steps, n_grp, n_beats);
        $fclose(fd);
        if (rc != 3) begin
            $display("RESULT: FAIL (cannot read w_cfg.txt)");
            $finish;
        end
        $readmemh("build/real/w_cmd.hex", cmd_mem);
        $readmemh("build/real/w_frame.hex", frame, 0, n_beats - 1);
        $readmemh("build/real/w_exp.hex", exp_mem, 0, k_steps - 1);
        $display("cfg: k_steps=%0d n_grp=%0d beats=%0d", k_steps, n_grp, n_beats);
    end

    // ---------------- debug monitor ----------------
    always @(posedge clk) begin
        if (rst_n && $test$plusargs("dbg")) begin
            if (desc_valid !== 2'b00)
                $display("t=%0t desc_valid=%b desc0=%h sel_ready=%b rd_state=%0d",
                         $time, desc_valid, desc0, sel_ready, u_rd.state);
        end
    end

    // ---------------- DUT wiring ----------------
    reg          wload_valid = 0;
    wire         wload_ready;
    reg  [127:0] data = 0;
    reg          data_valid = 0;
    wire         data_ready;
    reg          data_last = 0;
    wire         done_valid;
    reg          done_ready = 0;
    wire [15:0]  done_status;

    wire         free0, free1;
    wire [1:0]   fill_start, publish, abort_;
    wire [`NPU_WTILE_W-1:0] desc;
    wire [1:0]   commit_done;
    wire [31:0]  commit_status;
    wire [1:0]   wr_en;
    wire         wr_kind, wr_half;
    wire [2:0]   wr_grp;
    wire [7:0]   wr_addr;
    wire [127:0] wr_data;

    reg          sel_valid = 0;
    wire         sel_ready;
    reg  [15:0]  sel_job = 0, sel_tile = 0, sel_s = 0;
    reg  [1:0]   sel_mode = 0;
    reg  [3:0]   sel_g = 0;

    wire          b_valid;
    reg           b_ready = 0;
    wire [2303:0] b_data;
    wire [15:0]   b_step;
    wire          b_last;
    wire          td_valid;
    reg           td_ready = 0;
    wire [15:0]   td_status;

    wire          q_match, q_fault;

    weight_loader #(.GROUPS(GROUPS), .K_STEPS(K_STEPS)) u_ld (
        .clk_io(clk), .rst_io_n(rst_n),
        .wload_valid(wload_valid), .wload_ready(wload_ready),
        .wload_cmd(cmd_mem[0]),
        .data_valid(data_valid), .data_ready(data_ready),
        .data(data), .data_last(data_last), .data_error(1'b0),
        .done_valid(done_valid), .done_ready(done_ready),
        .done_status(done_status),
        .bank_free({free1, free0}),
        .bank_fill_start(fill_start), .bank_publish(publish),
        .bank_abort(abort_), .bank_desc(desc),
        .bank_commit_done(commit_done),
        .bank_commit_status(commit_status),
        .bank_wr_en(wr_en), .wr_kind(wr_kind), .wr_grp(wr_grp),
        .wr_half(wr_half), .wr_addr(wr_addr), .wr_data(wr_data)
    );

    wire [`NPU_WTILE_W-1:0]        desc0, desc1;
    wire [1:0]           desc_valid, accept, rel, rel_done;
    wire [15:0]          rel_status_0, rel_status_1;
    wire                 busy0, busy1;
    wire [2*GROUPS-1:0]  rd_en;
    wire [7:0]           rd_addr;
    wire [1:0]           rd_valid;
    wire [2*GROUPS*256-1:0] wlo_hi;
    wire [2*GROUPS*128-1:0] scale;

    weight_bank #(.GROUPS(GROUPS), .K_STEPS(K_STEPS)) u_b0 (
        .clk_io(clk), .rst_io_n(rst_n), .clk_core(clk), .rst_core_n(rst_n),
        .io_free(free0), .io_fill_start(fill_start[0]),
        .io_publish(publish[0]), .io_abort(abort_[0]), .io_desc(desc),
        .io_commit_done(commit_done[0]), .io_commit_status(commit_status[15:0]),
        .wr_en(wr_en[0]), .wr_kind(wr_kind), .wr_grp(wr_grp),
        .wr_half(wr_half), .wr_addr(wr_addr), .wr_data(wr_data),
        .core_desc_valid(desc_valid[0]), .core_desc(desc0),
        .core_accept(accept[0]), .core_release(rel[0]),
        .core_release_done(rel_done[0]),
        .core_release_status(rel_status_0),
        .core_busy(busy0),
        .rd_en(rd_en[0 +: GROUPS]), .rd_addr(rd_addr),
        .rd_valid(rd_valid[0]),
        .weight_lo_hi(wlo_hi[0 +: GROUPS*256]),
        .scale_word(scale[0 +: GROUPS*128])
    );

    weight_bank #(.GROUPS(GROUPS), .K_STEPS(K_STEPS)) u_b1 (
        .clk_io(clk), .rst_io_n(rst_n), .clk_core(clk), .rst_core_n(rst_n),
        .io_free(free1), .io_fill_start(fill_start[1]),
        .io_publish(publish[1]), .io_abort(abort_[1]), .io_desc(desc),
        .io_commit_done(commit_done[1]), .io_commit_status(commit_status[31:16]),
        .wr_en(wr_en[1]), .wr_kind(wr_kind), .wr_grp(wr_grp),
        .wr_half(wr_half), .wr_addr(wr_addr), .wr_data(wr_data),
        .core_desc_valid(desc_valid[1]), .core_desc(desc1),
        .core_accept(accept[1]), .core_release(rel[1]),
        .core_release_done(rel_done[1]),
        .core_release_status(rel_status_1),
        .core_busy(busy1),
        .rd_en(rd_en[GROUPS +: GROUPS]), .rd_addr(rd_addr),
        .rd_valid(rd_valid[1]),
        .weight_lo_hi(wlo_hi[GROUPS*256 +: GROUPS*256]),
        .scale_word(scale[GROUPS*128 +: GROUPS*128])
    );

    weight_reader #(.GROUPS(GROUPS), .K_STEPS(K_STEPS)) u_rd (
        .clk_core(clk), .rst_core_n(rst_n),
        .select_valid(sel_valid), .select_ready(sel_ready),
        .select_job(sel_job), .select_tile(sel_tile),
        .select_mode(sel_mode), .select_g(sel_g), .select_s(sel_s),
        .b_valid(b_valid), .b_ready(b_ready), .b_data(b_data),
        .b_step(b_step), .b_last(b_last),
        .tile_done_valid(td_valid), .tile_done_ready(td_ready),
        .tile_done_status(td_status),
        .query_job(16'd0), .query_tile(16'd0), .query_mode(2'd0),
        .query_g(4'd0), .query_s(16'd0),
        .query_match(q_match), .query_fault(q_fault),
        .bank_desc_valid(desc_valid), .bank_desc({desc1, desc0}),
        .bank_accept(accept), .bank_release(rel),
        .bank_release_done(rel_done),
        .bank_release_status({rel_status_1, rel_status_0}),
        .bank_rd_en(rd_en), .bank_rd_addr(rd_addr),
        .bank_rd_valid(rd_valid), .bank_wlo_hi(wlo_hi),
        .bank_scale(scale), .fatal()
    );

    // ---------------- tests ----------------
    integer i, step, bad;

    initial begin
        repeat (4) @(negedge clk);
        rst_n = 1;
        repeat (4) @(negedge clk);

        // ---- load the frame ----
        wload_valid = 1'b1;
        while (!wload_ready) @(negedge clk);
        @(posedge clk);
        @(negedge clk);
        wload_valid = 1'b0;

        for (i = 0; i < n_beats; i = i + 1) begin
            data       = frame[i];
            data_valid = 1'b1;
            data_last  = (i == n_beats - 1);
            while (!data_ready) @(negedge clk);
            @(posedge clk);
            @(negedge clk);
        end
        data_valid = 1'b0; data_last = 1'b0;

        done_ready = 1'b1;
        while (!done_valid) @(negedge clk);
        $display("LOAD_W done status=%04x (expect 0000)", done_status);
        if (done_status !== 16'h0000) errors = errors + 1;
        @(negedge clk); done_ready = 1'b0;
        repeat (4) @(negedge clk);

        // ---- select the tile and check every B beat ----
        sel_job = 16'd2; sel_tile = 16'd0; sel_mode = 2'd0;
        sel_g = n_grp[3:0]; sel_s = k_steps[15:0];
        // The handshake is sampled at the rising edge: sel_ready is
        // combinational on the select fields, so it must not be tested in the
        // same time step they are assigned.
        sel_valid = 1'b1;
        @(posedge clk);
        while (!sel_ready) @(posedge clk);
        $display("t=%0t select accepted", $time);
        @(negedge clk); sel_valid = 1'b0;
        $display("selected, streaming");

        b_ready = 1'b1;
        for (step = 0; step < k_steps; step = step + 1) begin
            while (!b_valid) @(negedge clk);
            #1;
            bad = 0;
            if (b_data !== exp_mem[step]) bad = 1;
            if (b_step !== step[15:0])    bad = 1;
            if (bad) begin
                errors = errors + 1;
                $display("FAIL: B beat %0d mismatch (step field %0d)",
                         step, b_step);
                if (errors <= 2)
                    $display("  got %h\n  exp %h", b_data, exp_mem[step]);
            end
            @(posedge clk);
            @(negedge clk);
        end
        b_ready = 1'b0;

        $display("all beats checked");
        td_ready = 1'b1;
        while (!td_valid) @(negedge clk);
        $display("tile_done status=%04x", td_status);
        if (td_status !== 16'h0000) errors = errors + 1;
        @(negedge clk); td_ready = 1'b0;

        if (errors == 0) $display("RESULT: PASS (%0d beats checked)", k_steps);
        else             $display("RESULT: FAIL (%0d errors)", errors);
        $finish;
    end

    initial begin
        #5000000;
        $display("RESULT: FAIL (timeout)");
        $finish;
    end

endmodule
